cd /testbed && mkdir -p test_pkg && cat > test_pkg/decorators.py << 'EOF'
import functools

def my_decorator(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper
EOF

